var pw = root.querySelector('.pw .inp');
var peek = root.querySelector('.peek');
var caps = root.querySelector('.caps');
var btn = root.querySelector('.submit');
var txt = root.querySelector('.txt');
var timers = [];

peek.addEventListener('click', function () {
  var shown = peek.getAttribute('aria-pressed') === 'true';
  peek.setAttribute('aria-pressed', shown ? 'false' : 'true');
  peek.setAttribute('aria-label', shown ? 'Show password' : 'Hide password');
  pw.type = shown ? 'password' : 'text';
  pw.focus();
});

function capsCheck(ev) {
  if (!ev.getModifierState) return;
  caps.hidden = !ev.getModifierState('CapsLock');
}
pw.addEventListener('keydown', capsCheck);
pw.addEventListener('keyup', capsCheck);
pw.addEventListener('blur', function () { caps.hidden = true; });

btn.addEventListener('click', function () {
  if (btn.dataset.state !== 'idle') return;
  btn.dataset.state = 'busy';
  btn.disabled = true;
  txt.textContent = 'Signing in';
  timers.push(setTimeout(function () {
    if (!root.isConnected) return;
    btn.dataset.state = 'done';
    txt.textContent = 'Signed in';
    timers.push(setTimeout(function () {
      if (!root.isConnected) return;
      btn.dataset.state = 'idle';
      btn.disabled = false;
      txt.textContent = 'Sign in';
    }, 1600));
  }, 1100));
});

