var cells = Array.prototype.slice.call(root.querySelectorAll('.cell'));
var verify = root.querySelector('.verify');
var resend = root.querySelector('.resend');
var tick = root.querySelector('.t');
var hint = root.querySelector('.hint');
var left = 30;
var timer = null;

function value() {
  return cells.map(function (c) { return c.value; }).join('');
}
function sync() {
  cells.forEach(function (c) { c.dataset.filled = c.value ? '1' : '0'; });
  var full = value().length === 6;
  verify.disabled = !full;
  if (full && root.dataset.state !== 'ok') hint.textContent = 'Code complete. Press Verify.';
  if (!full && root.dataset.state !== 'ok') hint.textContent = 'Paste the whole code and it fills every box.';
}
function digits(s) {
  return (s || '').replace(/\D+/g, '');
}
function spread(start, str) {
  var i = start;
  digits(str).split('').forEach(function (d) {
    if (i < cells.length) { cells[i].value = d; i += 1; }
  });
  cells[Math.min(i, cells.length - 1)].focus();
  sync();
}

cells.forEach(function (cell, i) {
  cell.addEventListener('input', function () {
    var d = digits(cell.value);
    if (d.length > 1) { spread(i, d); return; }
    cell.value = d;
    if (d && i < cells.length - 1) cells[i + 1].focus();
    sync();
  });
  cell.addEventListener('keydown', function (ev) {
    if (ev.key === 'Backspace' && !cell.value && i > 0) {
      ev.preventDefault();
      cells[i - 1].value = '';
      cells[i - 1].focus();
      sync();
    } else if (ev.key === 'ArrowLeft' && i > 0) {
      ev.preventDefault(); cells[i - 1].focus();
    } else if (ev.key === 'ArrowRight' && i < cells.length - 1) {
      ev.preventDefault(); cells[i + 1].focus();
    } else if (ev.key === 'Enter' && !verify.disabled) {
      verify.click();
    }
  });
  cell.addEventListener('paste', function (ev) {
    ev.preventDefault();
    var data = ev.clipboardData ? ev.clipboardData.getData('text') : '';
    spread(i, data);
  });
  cell.addEventListener('focus', function () { cell.select(); });
});

verify.addEventListener('click', function () {
  root.dataset.state = 'ok';
  hint.textContent = 'Code accepted. Finishing sign-in.';
  verify.disabled = true;
  verify.textContent = 'Verified';
  cells.forEach(function (c) { c.readOnly = true; });
});

timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  left -= 1;
  if (left > 0) { tick.textContent = String(left); return; }
  clearInterval(timer);
  resend.disabled = false;
  resend.textContent = 'Resend code';
}, 1000);

resend.addEventListener('click', function () {
  if (resend.disabled) return;
  resend.disabled = true;
  left = 30;
  resend.innerHTML = 'Resend in <b class="t">30</b>s';
  tick = root.querySelector('.t');
  root.dataset.state = '';
  verify.textContent = 'Verify';
  cells.forEach(function (c) { c.readOnly = false; c.value = ''; });
  cells[0].focus();
  sync();
  timer = setInterval(function () {
    if (!root.isConnected) { clearInterval(timer); return; }
    left -= 1;
    if (left > 0) { tick.textContent = String(left); return; }
    clearInterval(timer);
    resend.disabled = false;
    resend.textContent = 'Resend code';
  }, 1000);
});

sync();

