var go = root.querySelector('.go');
var cancel = root.querySelector('.cancel');
var status = root.querySelector('.status');
var jobs = [];

function reset(msg) {
  root.dataset.state = 'idle';
  go.disabled = false;
  cancel.disabled = false;
  go.textContent = 'Continue';
  status.textContent = msg;
}

go.addEventListener('click', function () {
  if (root.dataset.state !== 'idle') return;
  root.dataset.state = 'scan';
  go.disabled = true;
  go.textContent = 'Waiting';
  status.textContent = 'Touch the sensor to confirm it is you.';
  jobs.push(setTimeout(function () {
    if (!root.isConnected) return;
    root.dataset.state = 'ok';
    status.textContent = 'Authenticated with Touch ID.';
    jobs.push(setTimeout(function () {
      if (!root.isConnected) return;
      reset('Your passkey never leaves this device.');
    }, 2000));
  }, 1500));
});

cancel.addEventListener('click', function () {
  jobs.forEach(clearTimeout);
  jobs = [];
  reset('Cancelled. You can sign in with a password instead.');
});

