var inp = root.querySelector('.inp');
var verdict = root.querySelector('.verdict');
var bits = root.querySelector('.bits');
var crack = root.querySelector('.crack');
var reqs = Array.prototype.slice.call(root.querySelectorAll('.reqs li'));
var WORDS = ['password', 'qwerty', 'admin', 'letmein', 'welcome', 'harbor', 'dragon', 'monkey', 'iloveyou', 'login'];
var LABELS = ['Very weak', 'Weak', 'Fair', 'Good', 'Strong'];

function hasRun(s) {
  var low = s.toLowerCase();
  for (var i = 0; i + 2 < low.length; i += 1) {
    var a = low.charCodeAt(i), b = low.charCodeAt(i + 1), c = low.charCodeAt(i + 2);
    if (b - a === 1 && c - b === 1) return true;
    if (a === b && b === c) return true;
  }
  return false;
}

function score(s) {
  var pool = 0;
  var lower = /[a-z]/.test(s), upper = /[A-Z]/.test(s);
  var num = /[0-9]/.test(s), sym = /[^A-Za-z0-9]/.test(s);
  if (lower) pool += 26;
  if (upper) pool += 26;
  if (num) pool += 10;
  if (sym) pool += 32;
  var low = s.toLowerCase();
  var common = WORDS.some(function (w) { return low.indexOf(w) > -1; });
  var run = hasRun(s);
  var e = s.length && pool ? s.length * (Math.log(pool) / Math.log(2)) : 0;
  if (common) e -= 14;
  if (run) e -= 8;
  if (e < 0) e = 0;
  return {
    bits: Math.round(e),
    len: s.length >= 12,
    mix: lower && upper,
    num: num,
    sym: sym,
    safe: s.length > 0 && !common && !run
  };
}

function crackLabel(b) {
  if (b < 28) return 'seconds to crack';
  if (b < 36) return 'minutes to crack';
  if (b < 50) return 'days to crack';
  if (b < 66) return 'years to crack';
  return 'centuries to crack';
}

function render() {
  var r = score(inp.value);
  var band = r.bits < 24 ? 0 : r.bits < 36 ? 1 : r.bits < 48 ? 2 : r.bits < 64 ? 3 : 4;
  root.dataset.score = inp.value ? String(band) : '';
  verdict.textContent = inp.value ? LABELS[band] : 'Empty';
  bits.textContent = r.bits + ' bits';
  crack.textContent = inp.value ? crackLabel(r.bits) : 'nothing to measure';
  reqs.forEach(function (li) {
    li.classList.toggle('ok', !!r[li.dataset.k]);
  });
}

inp.addEventListener('input', render);
render();

