var methods = Array.prototype.slice.call(root.querySelectorAll('.m'));
var code = root.querySelector('.code');
var next = root.querySelector('.next');
var hint = root.querySelector('.hint');
var arc = root.querySelector('.arc');
var leftEl = root.querySelector('.left');
var HINTS = {
  app: 'Open your authenticator app and enter the current code.',
  sms: 'We can text a fresh code to the phone ending 04.',
  backup: 'Enter one of the backup codes you saved when you set this up.'
};
var PLACE = { app: '000 000', sms: '000 000', backup: 'abcd-efgh' };
var CIRC = 81.7;
var left = 30;

function pick(btn) {
  methods.forEach(function (m) {
    var on = m === btn;
    m.setAttribute('aria-checked', on ? 'true' : 'false');
    m.tabIndex = on ? 0 : -1;
  });
  root.dataset.m = btn.dataset.m;
  hint.textContent = HINTS[btn.dataset.m];
  code.placeholder = PLACE[btn.dataset.m];
  code.maxLength = btn.dataset.m === 'backup' ? 12 : 7;
  code.value = '';
  next.disabled = true;
  btn.focus();
}

methods.forEach(function (m, i) {
  m.addEventListener('click', function () { pick(m); });
  m.addEventListener('keydown', function (ev) {
    var d = 0;
    if (ev.key === 'ArrowDown' || ev.key === 'ArrowRight') d = 1;
    if (ev.key === 'ArrowUp' || ev.key === 'ArrowLeft') d = -1;
    if (!d) return;
    ev.preventDefault();
    pick(methods[(i + d + methods.length) % methods.length]);
  });
});

code.addEventListener('input', function () {
  if (root.dataset.m === 'backup') {
    next.disabled = code.value.trim().length < 6;
    return;
  }
  var d = code.value.replace(/\D+/g, '').slice(0, 6);
  code.value = d.length > 3 ? d.slice(0, 3) + ' ' + d.slice(3) : d;
  next.disabled = d.length !== 6;
});

next.addEventListener('click', function () {
  if (next.disabled) return;
  next.disabled = true;
  next.textContent = 'Verified';
  hint.textContent = 'Device confirmed. Continuing to the last step.';
});

var timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  left = left > 1 ? left - 1 : 30;
  leftEl.textContent = String(left);
  arc.setAttribute('stroke-dashoffset', String(CIRC * (30 - left) / 30));
  arc.setAttribute('stroke', left <= 5 ? '#fbbf24' : '#60a5fa');
}, 1000);

