  tip.textContent = 'Address updated locally. Send a fresh link when ready.';
}

edit.addEventListener('click', function () {
  if (addrin.hidden) {
    addrin.value = addr.textContent;
    addrin.hidden = false;
    addr.hidden = true;
    edit.textContent = 'Save';
    addrin.focus();
    addrin.select();
  } else {
    commit();
  }
});

addrin.addEventListener('keydown', function (ev) {
  if (ev.key === 'Enter') { ev.preventDefault(); commit(); }
  if (ev.key === 'Escape') { addrin.value = addr.textContent; commit(); }
});

resend.addEventListener('click', function () {
  if (resend.disabled) return;
  cool = 45;
  expiry = 598;
  resend.disabled = true;
  resend.innerHTML = 'Resend in <b class="c">45</b>s';
  counter = root.querySelector('.c');
  tip.textContent = 'A new link is on the way to ' + addr.textContent + '.';
});

openBtn.addEventListener('click', function () {
  tip.textContent = 'Switch to your mail app and tap the newest Northwind message.';
});

var timer = setInterval(function () {
  if (!root.isConnected) { clearInterval(timer); return; }
  if (expiry > 0) {
    expiry -= 1;
    clock.textContent = mmss(expiry);
  }
  if (cool > 0) {
    cool -= 1;
    if (cool === 0) {
      resend.disabled = false;
      resend.textContent = 'Resend link';
    } else if (counter) {
      counter.textContent = String(cool);
    }
  }
}, 1000);

