js:
var accounts = Array.prototype.slice.call(root.querySelectorAll('.acc'));
var cur = root.querySelector('.cur');
var note = root.querySelector('.note');
var add = root.querySelector('.add');
var signout = root.querySelector('.lnk');

function focusAt(i) {
  var t = accounts[(i + accounts.length) % accounts.length];
  accounts.forEach(function (a) { a.tabIndex = a === t ? 0 : -1; });
  t.focus();
}

function select(btn) {
  accounts.forEach(function (a) {
    a.setAttribute('aria-pressed', a === btn ? 'true' : 'false');
    a.tabIndex = a === btn ? 0 : -1;
  });
  var name = btn.querySelector('b').textContent;
  cur.textContent = btn.querySelector('.em').textContent;
  note.textContent = 'Switched to ' + name + '.';
  btn.focus();
}

accounts.forEach(function (a, i) {
  a.addEventListener('click', function () { select(a); });
  a.addEventListener('keydown', function (ev) {
    if (ev.key === 'ArrowDown') { ev.preventDefault(); focusAt(i + 1); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); focusAt(i - 1); }
    else if (ev.key === 'Home') { ev.preventDefault(); focusAt(0); }
    else if (ev.key === 'End') { ev.preventDefault(); focusAt(accounts.length - 1); }
  });
});

add.addEventListener('click', function () {
  note.textContent = 'Pick a provider to add an account.';
});

signout.addEventListener('click', function () {
  note.textContent = 'This would end all three sessions.';
});
